import { useTheme } from '@emotion/react';
import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';

import { Stack, Typography } from '@mui/material';

import FunTypo from 'components/ui/FunTypo';
import MainButton from 'components/ui/MainButton';
import { getRegions } from 'data/data';
import { GameUtil } from 'model/game/GameUtil';
import { reStartGame } from 'store/actions';
import { useCurrentGame, useGameCategory, useGameConfig } from 'store/selector';
import { pxToRem } from 'util/util';

const styles = {
    main: {
        display: 'flex',
        alignItems: 'center',
        flexDirection: 'column',
        justifyContent: 'center',
        position: 'relative',
        margin: `${pxToRem(16)} 0`,
        flexGrow: 1,
        width: '100%',
    },
    textGameCat: {
        display: 'block',
        fontSize: pxToRem(32),
        lineHeight: pxToRem(40),
        fontWeight: 800,
        textAlign: 'center',
        marginBottom: pxToRem(-8),
    },
    textFinalScore: {
        display: 'block',
        marginTop: pxToRem(16),
    },
    playAgain: {
        display: 'block',
        marginTop: pxToRem(24),
    },
};
const GameEnd = () => {
    const dispatch = useDispatch();
    const theme = useTheme();
    const { t, i18n } = useTranslation();
    const game = useCurrentGame();
    const gameConfig = useGameConfig();
    const gameCategory = useGameCategory();
    const regions = getRegions();
    const region = regions[game.region];

    const handleClickPlayAgain = () => {
        dispatch(reStartGame());
    };

    return (
        <Stack {...styles.main}>
            <Typography component="span" color="primary" {...styles.textGameCat}>
                {gameCategory?.name[i18n.language]}
            </Typography>
            <Typography component="span" color="secondary" {...styles.textGameCat}>
                {region ? region[i18n.language] : t('World')}
            </Typography>
            <Typography component="span" color="success.main" {...styles.textGameCat}>
                {t(gameConfig?.difficultyLevels.find((d) => d.key === game.difficultyLevel).name)}
            </Typography>

            {!GameUtil.isFlashcard(game) && (
                <>
                    <Typography {...styles.textFinalScore}>
                        <FunTypo
                            text={t('Final_Score_1')}
                            color={theme.palette.text.title.replace('#', '')}
                            stroke={true}
                            strokeWidth={pxToRem(2)}
                            distance={pxToRem(4)}
                            sx={{
                                display: 'block',
                                fontSize: pxToRem(64),
                                lineHeight: pxToRem(72),
                                fontWeight: 800,
                                textAlign: 'center',
                                mb: pxToRem(-32),
                            }}
                        />
                        <FunTypo
                            text={t('Final_Score_2')}
                            color={theme.palette.text.title.replace('#', '')}
                            stroke={false}
                            strokeWidth={pxToRem(2)}
                            distance={pxToRem(5)}
                            sx={{
                                display: 'block',
                                fontSize: pxToRem(72),
                                lineHeight: pxToRem(84),
                                fontWeight: 800,
                                textAlign: 'center',
                            }}
                        />
                    </Typography>
                    <Stack
                        display="flex"
                        justifyContent="center"
                        alignItems="flex-end"
                        direction="row"
                        sx={{
                            width: 'auto',
                        }}>
                        <FunTypo
                            text={game.currentScore}
                            color={theme.palette.primary.main.replace('#', '')}
                            stroke={false}
                            distance={pxToRem(7)}
                            flexGrow={0}
                            sx={{
                                display: 'block',
                                fontSize: pxToRem(96),
                                lineHeight: pxToRem(108),
                                fontWeight: 800,
                                width: 'auto',
                            }}
                        />
                        <FunTypo
                            text={'/' + game.questions.length}
                            color={theme.palette.success.main.replace('#', '')}
                            stroke={false}
                            distance={pxToRem(7)}
                            flexGrow={0}
                            sx={{
                                display: 'block',
                                fontSize: pxToRem(72),
                                lineHeight: pxToRem(84),
                                fontWeight: 800,
                                width: 'auto',
                            }}
                        />
                    </Stack>
                </>
            )}
            <MainButton
                buttonP={{
                    color: 'primary',
                    size: 'large',
                    onClick: handleClickPlayAgain,
					sx: {...styles.playAgain}
                }}
			>
                {t('Play Again')}
            </MainButton>
        </Stack>
    );
};

export default GameEnd;
