import { useTheme } from '@emotion/react';
import * as React from 'react';
import { useTranslation } from 'react-i18next';

import { LinearProgress, Stack, Typography } from '@mui/material';

import FunTypo from 'components/ui/FunTypo';
import { GameUtil } from 'model/game/GameUtil';
import { useCurrentGame } from 'store/selector';
import { pxToRem } from 'util/util';

const styles = {
    main: {
        display: 'flex',
        alignItems: 'center',
        flexDirection: 'column',
        justifyContent: 'space-between',
        width: '100%',
        margin: `${pxToRem(16)} 0`,
    },
    rowText: {
        display: 'flex',
        alignItems: 'center',
        flexDirection: 'row',
        justifyContent: 'space-between',
        width: '100%',
        margin: `${pxToRem(4)} 0`,
    },
    textQuestion: {
        fontSize: pxToRem(18),
        textAlign: 'right',
        fontWeight: 700,
    },
    containerTextScore: {
        display: 'flex',
        alignItems: 'center',
        flexDirection: 'row',
        width: 'auto',
    },
    textScoreValue: {
        display: 'block',
        fontSize: pxToRem(20),
        lineHeight: pxToRem(24),
        fontWeight: 800,
        width: 'auto',
    },
    progress: {
        flexGrow: 1,
        marginRight: pxToRem(16),
        marginLeft: pxToRem(16),
        width: '100%',
    },
};

const GameProgress = () => {
    const theme = useTheme();
    const { t } = useTranslation();
    const game = useCurrentGame();

    return (
        <Stack {...styles.main}>
            <Stack {...styles.rowText}>
                <Typography {...styles.textQuestion}>
                    {t('Question')}: {GameUtil.getProgress(game)}
                </Typography>

                {!GameUtil.isFlashcard(game) && (
                    <Stack {...styles.containerTextScore}>
                        <Typography {...styles.textQuestion}>{t('Score')}:</Typography>
                        &nbsp;
                        <FunTypo
                            text={game.currentScore}
                            color={theme.palette.text.main.replace('#', '')}
                            stroke={false}
                            distance={pxToRem(2)}
                            flexGrow={0}
                            sx={styles.textScoreValue}
                        />
                    </Stack>
                )}
            </Stack>
            <LinearProgress
                color="success"
                variant="buffer"
                value={GameUtil.getProgressValue(game)}
                valueBuffer={GameUtil.getProgressValueBuffer(game)}
                sx={styles.progress}
            />
        </Stack>
    );
};

export default GameProgress;
